ValidationRule.errorConditionFormula:
/* Ensure Tanium or Partner is selected */
AND((isNew() || DATEVALUE( CreatedDate ) > DATEVALUE("2023-08-10")),RecordType.DeveloperName = "Standard", NOT(ISPICKVAL(POC_Led_By__c, "Tanium") ),NOT(ISPICKVAL(POC_Led_By__c, "Partner")) )
|| AND((isNew() || DATEVALUE( CreatedDate ) > DATEVALUE("2023-08-10")),RecordType.DeveloperName = "TaaS", NOT(ISPICKVAL(POC_Led_By__c, "Tanium") ),NOT(ISPICKVAL(POC_Led_By__c, "Partner")) )
